import { Controller, Get, Patch, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 개인정보 열람 이력에 남기는 대상 정보 구분과 접근 유형
const ACCESS_INFO_TYPE = '연말정산';
const ACCESS_TYPE = '조회';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function isNumeric(v: unknown): boolean {
  if (typeof v === 'number') {
    return Number.isFinite(v);
  }
  if (typeof v === 'string') {
    return /^-?\d+(\.\d+)?$/.test(v.trim());
  }
  return false;
}

@Controller('api/v1')
export class FnSfr03207Controller {
  @Get('/year-end-data')
  async listYearEndData(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const q = checks.queryOf(req.query);
    const yearText = String(q['targetYear'] ?? '');
    if (!/^\d{4}$/.test(yearText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '정산 대상 연도를 4자리 숫자로 입력해 주세요.');
    }
    const page = q['page'] === undefined || q['page'] === '' ? 0 : Number(q['page']);
    const sizeRaw = q['size'] === undefined || q['size'] === '' ? DEFAULT_SIZE : Number(q['size']);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(sizeRaw) || sizeRaw < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 쪽 크기가 올바르지 않습니다.');
    }
    const size = Math.min(sizeRaw, MAX_SIZE);
    return transaction(async (db) => {
      await db.execute(
        `INSERT INTO personal_info_access_log
           (employee_id, target_employee_id, target_info_type, access_type, accessed_at, created_at, updated_at)
         VALUES
           (CAST(:userId AS bigint), CAST(:userId AS bigint), :infoType, :accessType, now(), now(), now())`,
        { userId: user.id, infoType: ACCESS_INFO_TYPE, accessType: ACCESS_TYPE },
      );
      const items = await db.query(
        `SELECT year_end_data_id AS "yearEndDataId",
                year_end_item_id AS "yearEndItemId",
                target_year AS "targetYear",
                amount AS "amount",
                closing_status AS "closingStatus",
                attachment_id AS "attachmentId",
                remark AS "remark"
           FROM year_end_data
          WHERE employee_id = CAST(:userId AS bigint)
            AND target_year = CAST(:targetYear AS integer)
          ORDER BY year_end_data_id
          LIMIT :size OFFSET :offset`,
        { userId: user.id, targetYear: yearText, size, offset: page * size },
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total"
           FROM year_end_data
          WHERE employee_id = CAST(:userId AS bigint)
            AND target_year = CAST(:targetYear AS integer)`,
        { userId: user.id, targetYear: yearText },
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }

  @Patch('/year-end-data/:yearEndDataId')
  async updateYearEndData2(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const id = req.params['yearEndDataId'];
    const amount = data['amount'];
    const attachmentId = data['attachmentId'];
    const remark = data['remark'];
    const hasAmount = amount !== undefined && amount !== null && amount !== '';
    const hasAttachment = attachmentId !== undefined && attachmentId !== null && attachmentId !== '';
    const hasRemark = remark !== undefined && remark !== null;
    if (hasAmount && !isNumeric(amount)) {
      throw new ApiError(422, 'INVALID_YEAR_END_INPUT', '금액은 숫자로 입력해 주세요.');
    }
    if (hasAttachment && !/^\d+$/.test(String(attachmentId))) {
      throw new ApiError(422, 'INVALID_YEAR_END_INPUT', '증빙 첨부파일 형식이 올바르지 않습니다.');
    }
    if (hasRemark && (typeof remark !== 'string' || remark.length > 500)) {
      throw new ApiError(422, 'INVALID_YEAR_END_INPUT', '비고는 500자 이하의 글자로 입력해 주세요.');
    }
    if (!/^\d+$/.test(String(id))) {
      throw new ApiError(404, 'YEAR_END_DATA_NOT_FOUND', '본인의 해당 연말정산 자료가 없습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT closing_status AS "closingStatus"
           FROM year_end_data
          WHERE year_end_data_id = CAST(:id AS bigint)
            AND employee_id = CAST(:userId AS bigint)`,
        { id, userId: user.id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'YEAR_END_DATA_NOT_FOUND', '본인의 해당 연말정산 자료가 없습니다.');
      }
      if (rows[0]['closingStatus'] === '마감') {
        throw new ApiError(409, 'YEAR_END_INPUT_CLOSED', '마감된 자료는 마감 취소 전에는 수정할 수 없습니다.');
      }
      if (hasAttachment) {
        const files = await db.query(
          `SELECT attachment_id FROM attachment WHERE attachment_id = CAST(:attachmentId AS bigint)`,
          { attachmentId: String(attachmentId) },
        );
        if (files.length === 0) {
          throw new ApiError(422, 'INVALID_YEAR_END_INPUT', '증빙 첨부파일을 찾을 수 없습니다.');
        }
      }
      const updated = await db.query(
        `UPDATE year_end_data
            SET amount = COALESCE(CAST(:amount AS numeric), amount),
                attachment_id = COALESCE(CAST(:attachmentId AS bigint), attachment_id),
                remark = COALESCE(:remark, remark),
                updated_at = now()
          WHERE year_end_data_id = CAST(:id AS bigint)
            AND employee_id = CAST(:userId AS bigint)
        RETURNING year_end_data_id AS "yearEndDataId", closing_status AS "closingStatus"`,
        {
          id,
          userId: user.id,
          amount: hasAmount ? String(amount) : null,
          attachmentId: hasAttachment ? String(attachmentId) : null,
          remark: hasRemark ? remark : null,
        },
      );
      return updated[0];
    });
  }

  @Post('/year-end-data/:yearEndDataId/submit')
  @HttpCode(200)
  async submitYearEndData(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const id = req.params['yearEndDataId'];
    if (!/^\d+$/.test(String(id))) {
      throw new ApiError(404, 'YEAR_END_DATA_NOT_FOUND', '본인의 해당 연말정산 자료가 없습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT closing_status AS "closingStatus"
           FROM year_end_data
          WHERE year_end_data_id = CAST(:id AS bigint)
            AND employee_id = CAST(:userId AS bigint)`,
        { id, userId: user.id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'YEAR_END_DATA_NOT_FOUND', '본인의 해당 연말정산 자료가 없습니다.');
      }
      if (rows[0]['closingStatus'] === '마감') {
        throw new ApiError(409, 'YEAR_END_INPUT_CLOSED', '마감된 자료는 제출할 수 없습니다.');
      }
      // 제출 상태는 고정값 '신청' (가정)
      const updated = await db.query(
        `UPDATE year_end_data
            SET closing_status = '신청',
                updated_at = now()
          WHERE year_end_data_id = CAST(:id AS bigint)
            AND employee_id = CAST(:userId AS bigint)
        RETURNING closing_status AS "closingStatus"`,
        { id, userId: user.id },
      );
      return updated[0];
    });
  }
}

