import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Form,
  Field,
  TextInput,
  NumberInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

export default function FnSfr03207Page({ role, notify }: PageProps) {
  const [yearInput, setYearInput] = useState<string>(String(new Date().getFullYear()));
  const [targetYear, setTargetYear] = useState<string>(String(new Date().getFullYear()));
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const [editing, setEditing] = useState<Row | null>(null);
  const [submitting, setSubmitting] = useState<Row | null>(null);
  const [amount, setAmount] = useState<number | string>('');
  const [attachmentId, setAttachmentId] = useState<number | string>('');
  const [remark, setRemark] = useState('');
  const [yearError, setYearError] = useState('');

  const list = useData<Page>(
    () => call<Page>('GET', '/year-end-data', role, undefined, { targetYear, page, size: 20 }),
    [targetYear, page, role],
  );

  const search = () => {
    if (!/^\d{4}$/.test(yearInput)) {
      setYearError('정산 대상 연도를 4자리 숫자로 입력해 주세요.');
      return;
    }
    setYearError('');
    setPage(0);
    setTargetYear(yearInput);
    setSelected(null);
  };

  const reset = () => {
    const now = String(new Date().getFullYear());
    setYearInput(now);
    setYearError('');
    setPage(0);
    setTargetYear(now);
    setSelected(null);
  };

  const canChange = (row: Row) => row['closingStatus'] !== '마감';

  const openEdit = (row: Row) => {
    setAmount(row['amount'] === null || row['amount'] === undefined ? '' : (row['amount'] as number));
    setAttachmentId(row['attachmentId'] === null || row['attachmentId'] === undefined ? '' : (row['attachmentId'] as number));
    setRemark(row['remark'] === null || row['remark'] === undefined ? '' : String(row['remark']));
    setEditing(row);
  };

  const saveEdit = async () => {
    if (!editing) {
      return;
    }
    if (amount === '' && attachmentId === '' && remark === '') {
      throw new Error('수정할 내용을 하나 이상 입력해 주세요.');
    }
    const body: Row = {};
    if (amount !== '') {
      body['amount'] = amount;
    }
    if (attachmentId !== '') {
      body['attachmentId'] = attachmentId;
    }
    if (remark !== '') {
      body['remark'] = remark;
    }
    await call('PATCH', '/year-end-data/' + String(editing['yearEndDataId']), role, body);
    notify('연말정산 자료를 수정했습니다.');
    setEditing(null);
    setSelected(null);
    list.reload();
  };

  const doSubmit = async () => {
    if (!submitting) {
      return;
    }
    await call('POST', '/year-end-data/' + String(submitting['yearEndDataId']) + '/submit', role, {});
    notify('연말정산 자료를 제출했습니다.');
    setSubmitting(null);
    setSelected(null);
    list.reload();
  };

  const actions = (row: Row) => (
    <span>
      {canChange(row) && (
        <button className="ghost" onClick={(e) => { e.stopPropagation(); openEdit(row); }}>
          수정
        </button>
      )}
      {canChange(row) && (
        <button className="ghost" onClick={(e) => { e.stopPropagation(); setSubmitting(row); }}>
          제출
        </button>
      )}
    </span>
  );

  if (selected) {
    return (
      <div className="doc">
        <button className="ghost" onClick={() => setSelected(null)}>목록으로</button>
        <section className="box">
          <h2>연말정산 자료</h2>
          <Pairs
            items={[
              ['정산 대상 연도', String(selected['targetYear'])],
              ['연말정산 항목', <RefName table="year_end_item" role={role} value={selected['yearEndItemId']} />],
              ['금액', <Num value={selected['amount']} />],
              ['마감 상태', <Badge value={selected['closingStatus']} />],
              ['증빙 첨부파일', selected['attachmentId'] ? <RefName table="attachment" role={role} value={selected['attachmentId']} /> : '없음'],
              ['비고', selected['remark'] ? String(selected['remark']) : '없음'],
            ]}
          />
        </section>
        {canChange(selected) && (
          <section className="box">
            <h2>처리</h2>
            <button onClick={() => openEdit(selected)}>수정</button>
            <button className="ghost" onClick={() => setSubmitting(selected)}>제출</button>
          </section>
        )}
        {editing && (
          <Drawer title="연말정산 자료 수정" onClose={() => setEditing(null)}>
            <Form onSubmit={saveEdit} submit="저장">
              <Field label="금액">
                <NumberInput value={amount} onChange={setAmount} />
              </Field>
              <Field label="증빙 첨부파일">
                <LookupSelect table="attachment" role={role} value={attachmentId} onChange={setAttachmentId} />
              </Field>
              <Field label="비고" wide>
                <TextInput value={remark} onChange={setRemark} multiline />
              </Field>
            </Form>
          </Drawer>
        )}
        {submitting && (
          <Drawer title="연말정산 자료 제출" onClose={() => setSubmitting(null)}>
            <Form onSubmit={doSubmit} submit="제출" note="제출하면 자료가 신청 상태로 바뀝니다." />
          </Drawer>
        )}
      </div>
    );
  }

  const rows = list.data ? list.data.items : [];

  return (
    <div className="doc">
      <h1>개인 연말정산 자료</h1>
      <Filters onSearch={search} onReset={reset}>
        <Field label="정산 대상 연도" required>
          <TextInput value={yearInput} onChange={setYearInput} placeholder="예: 2024" />
        </Field>
      </Filters>
      {yearError && <ErrorText text={yearError} />}
      {list.error && <ErrorText text={list.error} />}
      <Band total={list.data ? list.data.total : 0} />
      <DataTable
        columns={[
          { key: 'targetYear', label: '정산 대상 연도' },
          { key: 'yearEndItemId', label: '연말정산 항목', render: (r) => <RefName table="year_end_item" role={role} value={r['yearEndItemId']} /> },
          { key: 'amount', label: '금액', render: (r) => <Num value={r['amount']} /> },
          { key: 'closingStatus', label: '마감 상태', render: (r) => <Badge value={r['closingStatus']} /> },
          { key: 'actions', label: '처리', render: actions },
        ]}
        rows={rows}
        onRowClick={(r) => setSelected(r)}
        empty="해당 연도에 입력된 연말정산 자료가 없습니다. 급여 담당자에게 항목 등록을 요청해 주세요."
      />
      {list.data && (
        <Pager page={list.data.page} size={list.data.size} total={list.data.total} onPage={setPage} />
      )}
      {editing && (
        <Drawer title="연말정산 자료 수정" onClose={() => setEditing(null)}>
          <Form onSubmit={saveEdit} submit="저장">
            <Field label="금액">
              <NumberInput value={amount} onChange={setAmount} />
            </Field>
            <Field label="증빙 첨부파일">
              <LookupSelect table="attachment" role={role} value={attachmentId} onChange={setAttachmentId} />
            </Field>
            <Field label="비고" wide>
              <TextInput value={remark} onChange={setRemark} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
      {submitting && (
        <Drawer title="연말정산 자료 제출" onClose={() => setSubmitting(null)}>
          <Form onSubmit={doSubmit} submit="제출" note="제출하면 자료가 신청 상태로 바뀝니다." />
        </Drawer>
      )}
    </div>
  );
}
